import {mountTimebox} from '../temponotes/timebox-ui.js?v=777de26bb8b3';
import {dayKey,duration,periodTotal} from '../temponotes/timebox-model.mjs?v=777de26bb8b3';
export function mountTimeboxHub(root,store,{visible=true}={}){
 root.innerHTML='<div class="temponote-workspace timebox-workspace split-boxes"><aside class="timebox-side time-section" aria-label="Timebox"></aside><div class="box-middle"><button type="button" class="task-adjust-toggle">ADJUST</button></div><aside class="timebox-side reps-section" aria-label="Repbox"></aside><dialog class="task-adjust-dialog" aria-label="Adjust time and reps"><header><div class="adjust-periods" role="group" aria-label="Adjustment period"><button type="button" data-adjust-period="today" aria-pressed="true">DAILY</button><button type="button" data-adjust-period="week" aria-pressed="false">WEEKLY</button><button type="button" data-adjust-period="month" aria-pressed="false">MONTHLY</button></div><button type="button" class="adjust-close" aria-label="Close adjustments">×</button></header><p class="adjust-window-note">WEEKLY: LAST 7 DAYS · MONTHLY: LAST 30 DAYS</p><h3>TIMEBOX</h3><div class="adjust-time-rows"></div><h3>REPBOX</h3><div class="adjust-rep-rows"></div><p class="adjust-error" role="alert" hidden></p></dialog></div>';
 const $=s=>root.querySelector(s),dialog=$('.task-adjust-dialog'),toggle=$('.task-adjust-toggle'),error=$('.adjust-error'),rows=new Map();let state={tasks:[],repTasks:[]},ready=false,busy=false,disposed=false,period='today';
 const facade=kind=>({subscribe:fn=>store.subscribe(data=>fn({...data,state:{tasks:kind==='reps'?data.state.repTasks||[]:data.state.tasks}})),act:action=>store.act({...action,kind})});
 const unmountTime=mountTimebox(root,facade('time'),{visible,kind:'time',side:$('.time-section')}),unmountReps=mountTimebox(root,facade('reps'),{visible,kind:'reps',side:$('.reps-section')});
 const formatReps=value=>Number(value.toFixed(2)).toLocaleString();
 function controls(){toggle.disabled=!ready;for(const button of dialog.querySelectorAll('button:not(.adjust-close)'))button.disabled=busy||!ready;for(const input of dialog.querySelectorAll('input'))input.disabled=busy||!ready;}
 function render(){if(disposed||!dialog.open)return;const present=new Set();for(const kind of ['time','reps'])for(const task of kind==='time'?state.tasks:state.repTasks||[]){const key=kind+':'+task.id;present.add(key);let row=rows.get(key);if(!row){row=document.createElement('div');row.className='task-adjust-row';row.dataset.kind=kind;row.dataset.id=task.id;row.innerHTML='<div class="adjust-task-heading"><strong></strong><output></output></div><div class="adjust-fields">'+(kind==='time'?'<label>HOURS<input type="number" inputmode="numeric" data-amount="hours" min="0" max="100000" step="1" value="0"></label><label>MINUTES<input type="number" inputmode="numeric" data-amount="minutes" min="0" max="59" step="1" value="0"></label>':'<label>REPS<input type="number" inputmode="numeric" data-amount="reps" min="0" max="1000000000" step="1" value="0"></label>')+'<button type="button" data-adjust="1">ADD</button><button type="button" data-adjust="-1">REMOVE</button></div>';rows.set(key,row);$(kind==='time'?'.adjust-time-rows':'.adjust-rep-rows').append(row);}row.querySelector('strong').textContent=task.name;row.querySelector('output').textContent=(kind==='time'?duration:formatReps)(periodTotal(task,Date.now(),period,kind));}for(const [key,row]of rows)if(!present.has(key)){row.remove();rows.delete(key);}controls();}
 toggle.addEventListener('click',()=>{if(!ready)return;dialog.showModal();error.hidden=true;render();});$('.adjust-close').addEventListener('click',()=>dialog.close());
 dialog.addEventListener('click',async event=>{const periodButton=event.target.closest('[data-adjust-period]');if(periodButton&&!busy){period=periodButton.dataset.adjustPeriod;for(const b of dialog.querySelectorAll('[data-adjust-period]'))b.setAttribute('aria-pressed',String(b===periodButton));render();return;}const button=event.target.closest('[data-adjust]'),row=button?.closest('.task-adjust-row');if(!row||busy||!ready)return;const kind=row.dataset.kind;let amount;if(kind==='reps')amount=Number(row.querySelector('[data-amount=reps]').value);else{const hours=Number(row.querySelector('[data-amount=hours]').value),minutes=Number(row.querySelector('[data-amount=minutes]').value);if(!Number.isInteger(hours)||hours<0||hours>100000||!Number.isInteger(minutes)||minutes<0||minutes>59){error.textContent='CHECK HOURS AND MINUTES';error.hidden=false;return;}amount=(hours*60+minutes)*60000;}if(!Number.isSafeInteger(amount)||amount<=0||amount>1000000000000){error.textContent='ENTER AN AMOUNT';error.hidden=false;return;}busy=true;controls();error.hidden=true;try{await store.act({type:'adjustPeriod',kind,id:row.dataset.id,period,amount:amount*Number(button.dataset.adjust),day:dayKey(new Date())});if(!disposed)for(const input of row.querySelectorAll('input'))input.value='0';}catch(e){if(!disposed){error.textContent=e.message;error.hidden=false;}}finally{busy=false;if(!disposed){render();controls();}}});
 const stop=store.subscribe(data=>{state=data.state;ready=data.ready;if(data.error&&dialog.open){error.textContent=data.error;error.hidden=false;}render();controls();}),tick=setInterval(()=>{if(dialog.open&&!document.hidden)render();},1000);
 return()=>{disposed=true;stop();clearInterval(tick);dialog.close();unmountTime();unmountReps();rows.clear();root.replaceChildren();};
}
